	@Test
	void opaqueAggregateReceivesOriginalEncounterOrderAcrossAliasJoin() throws Exception {
		String query = PREFIX + "SELECT (<" + ORDERED_AGGREGATE_IRI + ">(?value) AS ?sequence) WHERE { "
				+ "?source ex:input ?value . BIND(?source AS ?focus) ?focus ex:facet ?facetValue }";
		SoftAssertions softly = new SoftAssertions();
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openRepository("aggregate-adjacency-" + adjacency, adjacency);
			assertGenericSourceOrder(repository, adjacency);
			List<String> actualSequences = new ArrayList<>();
			for (String forcedStrategy : List.of("automatic", "nestedLoop")) {
				Observed observed = evaluate(repository, query, true,
						"automatic".equals(forcedStrategy) ? null : forcedStrategy);
				String actual = observed.rows().isEmpty() ? "<no-row>"
						: observed.rows().getFirst().getValue("sequence").stringValue();
				actualSequences.add(actual);
				writeEvidence("aggregate-adjacency-" + adjacency + "-" + forcedStrategy,
						query + "\nexpected=" + String.join(",", SOURCE_ORDER) + "\nactual=" + actual + "\n"
								+ "telemetry:\n" + observed.telemetry());
				softly.assertThat(observed.rows())
						.as("one scalar custom aggregate row for %s", forcedStrategy)
						.hasSize(1);
				softly.assertThat(observed.telemetry())
						.as("the %s query must execute a native aggregate route, adjacency=%s", forcedStrategy,
								adjacency)
						.contains("nativeInvocationsActual=1", "nativeExecutionPath=");
				if ("nestedLoop".equals(forcedStrategy)) {
					softly.assertThat(observed.telemetry())
							.as("the forced aggregate must actually select the sequential nested-loop route")
							.contains("strategy: SEQUENTIAL_FALLBACK[reason=CUSTOM_AGGREGATE_ORDER]",
									"nativeExecutionPath=aggState");
				}
				softly.assertThat(actual)
						.as("aggregate encounter order, adjacency=%s, route=%s; telemetry:\n%s",
								adjacency, forcedStrategy, observed.telemetry())
						.isEqualTo(String.join(",", SOURCE_ORDER));
			}
			softly.assertThat(actualSequences)
					.as("automatic and sequential aggregate routes agree, adjacency=%s", adjacency)
					.containsExactly(String.join(",", SOURCE_ORDER), String.join(",", SOURCE_ORDER));
		}
		softly.assertAll();
	}

	@Test
	void correlatedMemoRetainsOrderedAndOccupiedEntryBoundaries() throws Exception {
		String rowsQuery = correlatedAliasQuery("SELECT ?wanted ?value WHERE { ", " }");
		String orderedQuery = correlatedAliasQuery(
				"SELECT (<" + ORDERED_AGGREGATE_IRI + ">( ?wanted ) AS ?sequence) WHERE { ", " }");
		SoftAssertions softly = new SoftAssertions();
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openCorrelatedMemoRepository("correlated-memo-adjacency-" + adjacency,
					adjacency);
			Observed genericRows = evaluate(repository, rowsQuery, false, null);
			Map<String, Integer> expectedBag = Map.of(EX + "red|" + EX + "red", 5,
					EX + "blue|" + EX + "blue", 5);
			softly.assertThat(rowBag(genericRows.rows(), "wanted", "value"))
					.as("generic execution confirms five red and five blue correlated rows")
					.isEqualTo(expectedBag);

			for (String factorMode : List.of("disabled", "enabled")) {
				System.setProperty(FACTOR_TRANSPORT_FLAG, "disabled".equals(factorMode) ? "false" : "true");
				Observed unordered = evaluate(repository, rowsQuery, true, "nestedLoop");
				writeEvidence("correlated-memo-unordered-adjacency-" + adjacency + "-factor-" + factorMode,
						rowsQuery + "\nexpectedBag=" + expectedBag + "\nactualBag="
								+ rowBag(unordered.rows(), "wanted", "value") + "\nfacetSourceOpens="
								+ correlatedFacetSourceOpens(unordered.telemetry()) + "\ntelemetry:\n"
								+ unordered.telemetry());
				softly.assertThat(rowBag(unordered.rows(), "wanted", "value"))
						.as("unordered fresh entries retain the exact result bag, adjacency=%s, factor=%s",
								adjacency, factorMode)
						.isEqualTo(expectedBag);
				softly.assertThat(unordered.telemetry())
						.as("the unordered case must execute a native LMDB route")
						.contains("nativeInvocationsActual=1", "nativeExecutionPath=nestedLoop");
				softly.assertThat(correlatedFacetSourceOpens(unordered.telemetry()))
						.as("five duplicate left rows per wanted value require two complete captures")
						.isEqualTo(2L);

				Observed genericOrdered = evaluate(repository, orderedQuery, false, null);
				assertThat(genericOrdered.rows()).as("generic ordered aggregate returns one scalar row").hasSize(1);
				String genericSequence = genericOrdered.rows().getFirst().getValue("sequence").stringValue();
				String expectedSequence = String.join(",", CORRELATED_NATIVE_ORDER);
				for (String route : List.of("automatic", "nestedLoop")) {
					Observed ordered = "automatic".equals(route)
							? evaluateWithStrategyEvents(repository, orderedQuery,
									"correlated-memo-ordered-adjacency-" + adjacency + "-factor-" + factorMode,
									true, null)
							: evaluate(repository, orderedQuery, true, route);
					String actualSequence = ordered.rows().getFirst().getValue("sequence").stringValue();
					writeEvidence("correlated-memo-ordered-adjacency-" + adjacency + "-route-" + route,
							orderedQuery + "\ngenericSequence=" + genericSequence + "\noriginalNativeSequence="
									+ expectedSequence + "\nactualSequence="
									+ actualSequence + "\nfacetSourceOpens="
									+ correlatedFacetSourceOpens(ordered.telemetry()) + "\ntelemetry:\n"
									+ ordered.telemetry());
					if ("automatic".equals(route)) {
						softly.assertThat(ordered.telemetry())
								.as("ordered query executes the generated aggregate route, adjacency=%s", adjacency)
								.contains("nativeInvocationsActual=1", "nativeExecutionPath=irAggregate",
										"route: irAggregate");
					} else {
						softly.assertThat(ordered.telemetry())
								.as("ordered query executes the sequential aggregate route, adjacency=%s", adjacency)
								.contains("nativeInvocationsActual=1", "nativeExecutionPath=aggState",
										"strategy: SEQUENTIAL_FALLBACK[reason=CUSTOM_AGGREGATE_ORDER]");
					}
					softly.assertThat(actualSequence)
							.as("ordered custom aggregate matches generic encounter order, adjacency=%s, route=%s",
									adjacency, route)
							.isEqualTo(expectedSequence);
					long expectedFacetOpens = "automatic".equals(route) && adjacency ? 2L : 10L;
					softly.assertThat(correlatedFacetSourceOpens(ordered.telemetry()))
							.as("ordered boundary retains the original per-left-row fragment route, adjacency=%s, route=%s",
									adjacency, route)
							.isEqualTo(expectedFacetOpens);
				}
			}

			Observed first = evaluateFirstAndClose(repository, rowsQuery, "nestedLoop");
			assertThat(first.rows()).as("lazy correlated result yields its first row").hasSize(1);
			Observed reopened = evaluate(repository, rowsQuery, true, "nestedLoop");
			writeEvidence("correlated-memo-early-close-reopen-adjacency-" + adjacency,
					rowsQuery + "\nexpectedBag=" + expectedBag + "\nreopenedBag="
							+ rowBag(reopened.rows(), "wanted", "value") + "\nfacetSourceOpens="
							+ correlatedFacetSourceOpens(reopened.telemetry()) + "\n");
			softly.assertThat(rowBag(reopened.rows(), "wanted", "value"))
					.as("reopening after early close captures complete fragments, adjacency=%s", adjacency)
					.isEqualTo(expectedBag);
			softly.assertThat(correlatedFacetSourceOpens(reopened.telemetry()))
					.as("a new execution completes two independent correlation captures, adjacency=%s", adjacency)
					.isEqualTo(2L);

			ValueFactory valueFactory = repository.getValueFactory();
			Value shared = valueFactory.createIRI(EX, "correlated-shared");
			Map<String, Value> occupied = Map.of("source", shared);
			Observed genericOccupied = evaluate(repository, rowsQuery, false, null, occupied);
			assertThat(rowBag(genericOccupied.rows(), "wanted", "value"))
					.as("binding the alias to its compatible source preserves the generic bag")
					.isEqualTo(expectedBag);
			Observed nativeOccupied = evaluate(repository, rowsQuery, true, "nestedLoop", occupied);
			writeEvidence("correlated-memo-occupied-entry-adjacency-" + adjacency,
					rowsQuery + "\nexpectedBag=" + expectedBag + "\nactualBag="
							+ rowBag(nativeOccupied.rows(), "wanted", "value") + "\nfacetSourceOpens="
							+ correlatedFacetSourceOpens(nativeOccupied.telemetry()) + "\ntelemetry:\n"
							+ nativeOccupied.telemetry());
			softly.assertThat(rowBag(nativeOccupied.rows(), "wanted", "value"))
					.as("occupied alias entry preserves the exact result bag, adjacency=%s", adjacency)
					.isEqualTo(expectedBag);
			softly.assertThat(correlatedFacetSourceOpens(nativeOccupied.telemetry()))
					.as("occupied alias entries keep the original fragment route, adjacency=%s", adjacency)
					.isEqualTo(10L);
			softly.assertThat(nativeOccupied.telemetry())
					.as("the alias slot is occupied at native query entry, adjacency=%s", adjacency)
					.contains("initialBoundMask:");

			Map<String, Value> conflict = Map.of("source", valueFactory.createIRI(EX, "conflicting-source"));
			Observed genericConflict = evaluate(repository, rowsQuery, false, null, conflict);
			Observed nativeConflict = evaluate(repository, rowsQuery, true, "nestedLoop", conflict);
			softly.assertThat(genericConflict.rows())
					.as("the conflicting entry binding has no generic results")
					.isEmpty();
			softly.assertThat(rowBag(nativeConflict.rows(), "wanted", "value"))
					.as("native BIND conflict matches the exact empty generic bag, adjacency=%s", adjacency)
					.isEqualTo(rowBag(genericConflict.rows(), "wanted", "value"));
		}
		softly.assertAll();
	}

	@Test
	void correlatedMemoAggregateStrategyDiagnosticIncludesForcedSerialIr() throws Exception {
		String query = correlatedAliasQuery(
				"SELECT (<" + ORDERED_AGGREGATE_IRI + ">( ?wanted ) AS ?sequence) WHERE { ", " }");
		String expectedSequence = String.join(",", CORRELATED_NATIVE_ORDER);
		for (boolean adjacency : List.of(false, true)) {
			for (String factorMode : List.of("disabled", "enabled")) {
				System.setProperty(FACTOR_TRANSPORT_FLAG, "disabled".equals(factorMode) ? "false" : "true");
				SailRepository repository = openCorrelatedMemoRepository(
						"correlated-memo-route-diagnostic-adjacency-" + adjacency + "-factor-" + factorMode,
						adjacency);
				List<String> requestedRoutes = new ArrayList<>(List.of("automatic", "irAggregate", "nestedLoop"));
				if ("enabled".equals(factorMode)) {
					requestedRoutes.add("packedFtreeAggregate");
				}
				for (String requestedRoute : requestedRoutes) {
					String forcedRoute = "automatic".equals(requestedRoute) ? null : requestedRoute;
					String previousSynchronous = System.getProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY);
					if ("irAggregate".equals(requestedRoute)) {
						System.setProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
					}
					Observed observed;
					try {
						observed = evaluateWithStrategyEvents(repository, query,
								"correlated-memo-route-jfr-adjacency-" + adjacency + "-factor-" + factorMode
										+ "-requested-" + requestedRoute,
								true, forcedRoute);
					} finally {
						restoreProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, previousSynchronous);
					}
					String actualSequence = observed.rows().isEmpty() ? "<no-row>"
							: observed.rows().getFirst().getValue("sequence").stringValue();
					writeEvidence("correlated-memo-route-diagnostic-adjacency-" + adjacency + "-factor-"
							+ factorMode + "-requested-" + requestedRoute,
							"query:\n" + query + "\nadjacency=" + adjacency + "\nfactorMode=" + factorMode
									+ "\nrequestedRoute=" + requestedRoute + "\nexpectedSequence=" + expectedSequence
									+ "\nactualSequence=" + actualSequence + "\nfacetSourceOpens="
									+ correlatedFacetSourceOpens(observed.telemetry()) + "\ntelemetry:\n"
									+ observed.telemetry());
					assertThat(observed.rows())
							.as("aggregate route returns one result, adjacency=%s, factor=%s, requested=%s",
									adjacency, factorMode, requestedRoute)
							.hasSize(1);
					assertThat(actualSequence)
							.as("aggregate route preserves exact encounter sequence, adjacency=%s, factor=%s, requested=%s",
									adjacency, factorMode, requestedRoute)
							.isEqualTo(expectedSequence);
					if ("irAggregate".equals(requestedRoute)) {
						assertThat(observed.telemetry())
								.as("the forced serial request actually selects irAggregate")
								.contains("nativeExecutionPath=irAggregate", "route: irAggregate");
					}
				}
			}
		}
	}

	@Test
	void correlatedAliasOriginalNativeAggregateControl() throws Exception {
		String query = correlatedAliasQuery(
				"SELECT (<" + ORDERED_AGGREGATE_IRI + ">( ?wanted ) AS ?sequence) WHERE { ", " }");
		SoftAssertions softly = new SoftAssertions();
		List<String> actualSequences = new ArrayList<>();
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openCorrelatedMemoRepository("correlated-original-control-" + adjacency,
					adjacency);
			Observed generic = evaluate(repository, query, false, null);
			String genericSequence = generic.rows().getFirst().getValue("sequence").stringValue();
			String routeSequence = null;
			for (String route : List.of("automatic", "nestedLoop")) {
				Observed nativeResult = evaluate(repository, query, true,
						"automatic".equals(route) ? null : route);
				String sequence = nativeResult.rows().getFirst().getValue("sequence").stringValue();
				long sourceOpens = correlatedFacetSourceOpens(nativeResult.telemetry());
				writeEvidence("correlated-original-plan-adjacency-" + adjacency + "-route-" + route,
						"query:\n" + query + "\ngenericSequence=" + genericSequence + "\nactualSequence="
								+ sequence + "\ncorrelatedFacetSourceOpens=" + sourceOpens + "\ntelemetry:\n"
								+ nativeResult.telemetry());
				softly.assertThat(nativeResult.rows()).as("ordered native aggregate returns one row").hasSize(1);
				softly.assertThat(nativeResult.telemetry())
						.as("the exact original native join route is selected, adjacency=%s, route=%s",
								adjacency, route)
						.contains("guardedRightDriven=<unavailable:correlated-input>",
								"originalOrderMemo=CorrelatedFragmentMemo(");
				long expectedFacetOpens = "automatic".equals(route) && adjacency ? 2L : 10L;
				softly.assertThat(sourceOpens)
						.as("the original route opens the right fragment once per left row, adjacency=%s, route=%s",
								adjacency, route)
						.isEqualTo(expectedFacetOpens);
				softly.assertThat(sequence)
						.as("the original native query and route establish the expected encounter order, adjacency=%s, route=%s",
								adjacency, route)
						.isEqualTo(String.join(",", CORRELATED_NATIVE_ORDER));
				if ("automatic".equals(route)) {
					softly.assertThat(nativeResult.telemetry())
							.as("the automatic route executes the generated aggregate kernel")
							.contains("nativeExecutionPath=irAggregate", "route: irAggregate");
				} else {
					softly.assertThat(nativeResult.telemetry())
							.as("the forced route executes the sequential custom-aggregate fallback")
							.contains("nativeExecutionPath=aggState",
									"strategy: SEQUENTIAL_FALLBACK[reason=CUSTOM_AGGREGATE_ORDER]");
				}
				if (routeSequence == null) {
					routeSequence = sequence;
				} else {
					softly.assertThat(sequence)
							.as("generated and sequential original plans preserve one encounter order")
							.isEqualTo(routeSequence);
				}
				actualSequences.add(sequence);
			}
		}
		softly.assertThat(actualSequences)
				.as("both original routes preserve the encounter order in both adjacency modes")
				.containsExactly(actualSequences.get(0), actualSequences.get(0), actualSequences.get(0),
						actualSequences.get(0));
		softly.assertAll();
	}

	@Test
	void correlatedAliasPlanPreservesOrderAndOccupiedEntryGuards() throws Exception {
		String query = correlatedAliasQuery(
				"SELECT (<" + ORDERED_AGGREGATE_IRI + ">( ?wanted ) AS ?sequence) WHERE { ", " }");
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openCorrelatedMemoRepository("correlated-plan-guards-" + adjacency, adjacency);
			TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
			Group group = findGroup(parsed);
			assertThat(group).as("the custom aggregate group is parsed").isNotNull();
			LmdbStore store = (LmdbStore) repository.getSail();
			try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
						new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
						new EvaluationStatistics(), false);
				LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(group,
						new QueryEvaluationContext.Minimal((Dataset) null), strategy,
						(NativeLmdbQuerySource) dataset);
				assertThat(outcome.isSupported()).as("the correlated custom aggregate compiles natively").isTrue();
				assertThat(outcome.step()).isInstanceOf(NativeGroupStep.class);
				NativeGroupStep compiled = (NativeGroupStep) outcome.step();
				assertThat(compiled.arg).as("the compiler retains the outer repeatable equality filter")
						.isInstanceOf(FilterPlan.class);
				FilterPlan outerFilter = (FilterPlan) compiled.arg;
				assertThat(outerFilter.arg).as("the compiled input contains the alias join")
						.isInstanceOf(NativeAliasJoinPlan.class);
				NativeAliasJoinPlan compiledAlias = (NativeAliasJoinPlan) outerFilter.arg;
				SlotPlan correlatedRight = new FilterPlan(compiledAlias.original.right, outerFilter.filter,
						outerFilter.filterMask, outerFilter.termKindFilter);
				SlotPlan correlatedCandidate = NativeAliasJoinPlan.create(compiledAlias.original.left, correlatedRight);
				writeEvidence("correlated-plan-guards-adjacency-" + adjacency,
						"query:\n" + query + "\ncompiledPlan="
								+ LmdbNativeExplain.describe(compiled.arg, compiled.layout) + "\ncorrelatedCandidate="
								+ correlatedCandidate.getClass().getSimpleName() + "\n");
				assertThat(correlatedCandidate)
						.as("correlated memo remains behind the guarded alias-selection boundary")
						.isInstanceOf(NativeAliasJoinPlan.class);
				if (!(correlatedCandidate instanceof NativeAliasJoinPlan alias)) {
					continue;
				}
				assertThat(alias.inverted).as("externally correlated reads have no reversed alternative").isNull();
				RowState row = new RowState((NativeLmdbQuerySource) dataset, compiled.layout,
						EmptyBindingSet.getInstance(), group, new NativeCancellationToken());
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout))
						.as("normal row initialization succeeds")
						.isTrue();
				Integer sourceSlot = compiled.layout.slot("source");
				assertThat(sourceSlot).as("source has a compiled slot").isNotNull();
				assertThat(row.bind(sourceSlot, ((NativeLmdbQuerySource) dataset)
						.idOf(repository.getValueFactory().createIRI(EX, "correlated-shared"))))
								.as("the production row binding API occupies the source slot")
								.isTrue();
				long occupiedMask = row.boundMask();
				assertThat(occupiedMask & (1L << sourceSlot)).as("source is occupied at alias entry").isNotZero();
				assertThat(alias.select(row, occupiedMask, occupiedMask, false))
						.as("an occupied alias-entry slot keeps the original join")
						.isSameAs(alias.original);
				assertThat(alias.select(row, 0L, 0L, true))
						.as("an order-sensitive boundary keeps the original join")
						.isSameAs(alias.original);
				assertThat(alias.select(row, 0L, 0L, false))
						.as("a fresh unordered frame selects the memoized original-order route")
						.isSameAs(alias.memoized);
			}
		}
	}

	@Test
	void orderedUnionDistinctRetainsAliasMemoThroughLeaseAndWorkerClones() throws Exception {
		String query = PREFIX + "SELECT (COUNT(DISTINCT ?source) AS ?count) WHERE { "
				+ "{ ?source ex:input ?value . } UNION { ?source ex:input ?value . } "
				+ "BIND(?source AS ?focus) ?focus ex:facet ?facetValue . }";
		SailRepository repository = openRepository("ordered-union-alias-clones", false);
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		Group group = findGroup(parsed);
		assertThat(group).as("the DISTINCT aggregate group is parsed").isNotNull();
		LmdbStore store = (LmdbStore) repository.getSail();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(group,
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, (NativeLmdbQuerySource) dataset);
			assertThat(outcome.isSupported()).as("the DISTINCT alias query compiles natively").isTrue();
			assertThat(outcome.step()).isInstanceOf(NativeGroupStep.class);
			NativeGroupStep compiled = (NativeGroupStep) outcome.step();
			assertThat(compiled.arg).as("the compiled join retains its alias alternative")
					.isInstanceOf(NativeAliasJoinPlan.class);
			if (!(compiled.arg instanceof NativeAliasJoinPlan sourceAlias)) {
				return;
			}
			RowState row = new RowState((NativeLmdbQuerySource) dataset, compiled.layout,
					EmptyBindingSet.getInstance(), group, new NativeCancellationToken());
			assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout))
					.as("the DISTINCT planning frame initializes")
					.isTrue();
			Integer sourceSlot = compiled.layout.slot("source");
			assertThat(sourceSlot).as("the DISTINCT key has a native slot").isNotNull();
			NativeTupleDistinctPlan distinct = LmdbNativeOrderPlanner.tuple(compiled.arg,
					new int[] { sourceSlot }, row);
			assertThat(distinct.strategy).as("the UNION arms provide a proven subject order")
					.isEqualTo(NativeDistinctStrategy.ADJACENT);
			assertThat(distinct.arg).as("ordered DISTINCT keeps the proven alias and memo alternative")
					.isInstanceOf(NativeAliasJoinPlan.class);
			if (!(distinct.arg instanceof NativeAliasJoinPlan orderedAlias)) {
				return;
			}
			assertThat(orderedAlias.original.left).as("the UNION order remains beneath the alias BIND")
					.isInstanceOf(ExtensionPlan.class);
			if (orderedAlias.original.left instanceof ExtensionPlan extension) {
				assertThat(extension.arg).as("the two branches remain an explicit ordered UNION")
						.isInstanceOf(OrderedUnionPlan.class);
			}
			assertThat(orderedAlias.inverted).as("ordered execution disables only the inverted alternative").isNull();
			assertThat(orderedAlias.originalDrivingOrder)
					.as("ordered execution records its validated original-driving mode")
					.isTrue();
			assertThat(orderedAlias.freshMask).as("the original alias freshness guard remains intact")
					.isEqualTo(sourceAlias.freshMask);
			assertThat(orderedAlias.memoized.original).as("memo replay uses the proven original-driving join")
					.isSameAs(orderedAlias.original);
			assertThat(orderedAlias.select(row, 0L, 0L, false))
					.as("a fresh row keeps the original-order memo route")
					.isSameAs(orderedAlias.memoized);
			assertThat(orderedAlias.select(row, 0L, 0L, true))
					.as("an encounter-sensitive row keeps the ordered original join")
					.isSameAs(orderedAlias.original);
			assertThat(orderedAlias.select(null, 0L, 0L, false))
					.as("a missing row cannot select the alias alternative")
					.isSameAs(orderedAlias.original);
			assertThat(row.bind(sourceSlot, ((NativeLmdbQuerySource) dataset)
					.idOf(repository.getValueFactory().createIRI(EX, "source-A"))))
							.as("the source alias key can be occupied in the normal row frame")
							.isTrue();
			long occupiedMask = row.boundMask();
			assertThat(occupiedMask & orderedAlias.freshMask)
					.as("the occupied source intersects the alias freshness guard")
					.isNotZero();
			assertThat(orderedAlias.select(row, occupiedMask, occupiedMask, false))
					.as("an occupied alias key keeps the original ordered join")
					.isSameAs(orderedAlias.original);

			NativeFilterLease lease = new NativeFilterLease();
			SlotPlan leased = lease.borrow(orderedAlias);
			lease.discard();
			assertThat(leased).as("a filter-lease clone retains the pinned alias plan")
					.isInstanceOf(NativeAliasJoinPlan.class);
			if (leased instanceof NativeAliasJoinPlan leasedAlias) {
				assertThat(leasedAlias.inverted).as("lease cloning cannot re-enable inversion").isNull();
				assertThat(leasedAlias.originalDrivingOrder).isTrue();
				assertThat(leasedAlias.orderProof).isSameAs(orderedAlias.orderProof);
				assertThat(leasedAlias.freshMask).isEqualTo(orderedAlias.freshMask);
				assertThat(leasedAlias.original.producedMask()).isEqualTo(orderedAlias.original.producedMask());
				assertThat(LmdbNativeAggregateCompiler.memoReadMask(leasedAlias.original.right))
						.isEqualTo(LmdbNativeAggregateCompiler.memoReadMask(orderedAlias.original.right));
				assertThat(leasedAlias.original.left).isInstanceOf(ExtensionPlan.class);
				if (leasedAlias.original.left instanceof ExtensionPlan extension) {
					assertThat(extension.arg).isInstanceOf(OrderedUnionPlan.class);
				}
				assertThat(leasedAlias.memoized.original).isSameAs(leasedAlias.original);
			}

			NativeScalarPlan.WorkerContext workerContext = NativeScalarPlan.WorkerContext.forSource(
					(NativeLmdbQuerySource) dataset, null);
			assertThat(NativeWorkerPlanBinder.canBind(orderedAlias)).as("the pure UNION alias is worker-bindable")
					.isTrue();
			try (NativeWorkerPlanBinder binder = new NativeWorkerPlanBinder(workerContext)) {
				SlotPlan worker = binder.bind(orderedAlias);
				assertThat(worker).as("worker binding retains the guarded alias plan")
						.isInstanceOf(NativeAliasJoinPlan.class);
				if (worker instanceof NativeAliasJoinPlan workerAlias) {
					assertThat(workerAlias.inverted).as("worker binding cannot re-enable inversion").isNull();
					assertThat(workerAlias.originalDrivingOrder).isTrue();
					assertThat(workerAlias.orderProof).isSameAs(orderedAlias.orderProof);
					assertThat(workerAlias.freshMask).isEqualTo(orderedAlias.freshMask);
					assertThat(workerAlias.original.producedMask()).isEqualTo(orderedAlias.original.producedMask());
					assertThat(LmdbNativeAggregateCompiler.memoReadMask(workerAlias.original.right))
							.isEqualTo(LmdbNativeAggregateCompiler.memoReadMask(orderedAlias.original.right));
					assertThat(workerAlias.original.left).isInstanceOf(ExtensionPlan.class);
					if (workerAlias.original.left instanceof ExtensionPlan extension) {
						assertThat(extension.arg).isInstanceOf(OrderedUnionPlan.class);
					}
					assertThat(workerAlias.memoized.original).isSameAs(workerAlias.original);
				}
			}
		}
	}

