	@Test
	void automaticPhysicalAggregateAndOriginalJoinTriage() throws Exception {
		SoftAssertions softly = new SoftAssertions();
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openRepository("automatic-table-adjacency-" + adjacency, adjacency);
			for (boolean alias : List.of(true, false)) {
				String query = physicalAggregateQuery(alias);
				String name = "automatic-physical-adjacency-" + adjacency + (alias ? "-alias" : "-original-join");
				List<String> expectedOrder = alias || adjacency ? SOURCE_ORDER : ORIGINAL_JOIN_NO_ADJACENCY_ORDER;
				try {
					Observed observed = evaluate(repository, query, true, null);
					String sequence = observed.rows().isEmpty() ? "<no-row>"
							: observed.rows().getFirst().getValue("sequence").stringValue();
					writeEvidence(name, query + "\nexpected=" + String.join(",", expectedOrder)
							+ "\nactual=" + sequence + "\ntelemetry:\n" + observed.telemetry());
					softly.assertThat(observed.telemetry())
							.as("automatic aggregate route is native: %s", name)
							.contains("nativeExecutionPath=irAggregate");
					softly.assertThat(observed.rows())
							.as("automatic physical aggregate has one row: %s", name)
							.hasSize(1);
					softly.assertThat(sequence)
							.as("automatic result preserves source order: %s", name)
							.isEqualTo(String.join(",", expectedOrder));
					softly.assertThat(observed.rows().getFirst().getValue("length").stringValue())
							.as("automatic lexical length is correct: %s", name)
							.isEqualTo("11");
					if (alias) {
						softly.assertThat(observed.telemetry())
								.as("alias case uses the optimized alias plan: %s", name)
								.contains("AliasJoin(");
					} else {
						softly.assertThat(observed.telemetry())
								.as("control uses the original join shape: %s", name)
								.doesNotContain("AliasJoin(");
					}
				} catch (RuntimeException failure) {
					writeEvidence(name, query + "\nexception=" + failure.getClass().getName() + ": "
							+ failure.getMessage() + "\n");
					softly.assertThat(failure).as("automatic evaluation must complete: %s", name).isNull();
				}
			}
		}
		softly.assertAll();
	}

