	@Test
	void weightedCustomReducersKeepLogicalCallsAcrossTableDistinctAndAdaptiveRoutes() throws Exception {
		String query = PREFIX + "SELECT (<" + ORDERED_AGGREGATE_IRI + ">( ?value ) AS ?sequence) "
				+ "(COUNT(DISTINCT ?replica) AS ?distinctReplicas) WHERE { "
				+ "?source ex:input ?value . ?source ex:replica ?replica . "
				+ "BIND(?source AS ?focus) ?focus ex:facet ?facetValue }";
		String expectedSequence = String.join(",", List.of("A1", "A1", "A1", "A1", "A2", "A2", "A2", "A2",
				"B1", "B1", "B1", "B1", "B2", "B2", "B2", "B2"));
		SoftAssertions softly = new SoftAssertions();
		for (boolean adjacency : List.of(false, true)) {
			SailRepository repository = openWeightedTableRepository("weighted-custom-table-" + adjacency, adjacency);
			assertFacetMultiplicity(repository);
			AGGREGATE_CALLBACKS.set(0);
			Observed generic = evaluate(repository, query, false, null);
			writeEvidence("weighted-custom-table-generic-adjacency-" + adjacency,
					"query:\n" + query + "\nexpectedSequence=" + expectedSequence + "\ngenericRows="
							+ generic.rows() + "\ngenericCallbacks=" + generic.aggregateCallbacks() + "\n");
			softly.assertThat(generic.rows()).as("generic weighted custom aggregate produces one row").hasSize(1);
			if (!generic.rows().isEmpty()) {
				softly.assertThat(generic.rows().getFirst().getValue("sequence").stringValue())
						.as("the independent generic aggregate preserves every replica in source order")
						.isEqualTo(expectedSequence);
				softly.assertThat(generic.rows().getFirst().getValue("distinctReplicas").stringValue())
						.as("the two replica terms remain DISTINCT")
						.isEqualTo("2");
			}
			softly.assertThat(generic.aggregateCallbacks())
					.as("generic custom callback count equals its sixteen logical input rows")
					.isEqualTo(16);

			TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
			Group group = findGroup(parsed);
			softly.assertThat(group).as("the weighted custom aggregate group is present").isNotNull();
			LmdbStore store = (LmdbStore) repository.getSail();
			try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
						new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
						new EvaluationStatistics(), false);
				LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(group,
						new QueryEvaluationContext.Minimal((Dataset) null), strategy, (NativeLmdbQuerySource) dataset);
				softly.assertThat(outcome.isSupported()).as("the weighted custom aggregate compiles natively").isTrue();
				if (!outcome.isSupported() || !(outcome.step() instanceof NativeGroupStep compiled)) {
					continue;
				}
				SlotPlan sourceOrderInput = compiled.arg instanceof NativeAliasJoinPlan alias
						? alias.original
						: compiled.arg;
				SlotPlan aggregateSource = sourceOrderInput instanceof JoinPlan join ? join.left : sourceOrderInput;
				SlotPlan weightedInput = new WeightedFacetPlan(aggregateSource, 2L);
				List<Long> weights = collectPhysicalInputWeights(dataset, compiled, group, weightedInput);
				long logicalRows = weights.stream().mapToLong(Long::longValue).sum();
				writeEvidence("weighted-custom-table-input-adjacency-" + adjacency,
						"query:\n" + query + "\nadjacency=" + adjacency + "\ncompiledInput="
								+ LmdbNativeExplain.describe(compiled.arg, compiled.layout) + "\nweightedInput="
								+ LmdbNativeExplain.describe(aggregateSource, compiled.layout) + "\nweights=" + weights
								+ "\nlogicalRows=" + logicalRows + "\n");
				softly.assertThat(weights)
						.as("the real input rows carry their two omitted facet matches as weight")
						.anyMatch(weight -> weight > 1L);
				softly.assertThat(logicalRows)
						.as("weighted physical rows represent the exact logical bag")
						.isEqualTo(16L);

				AGGREGATE_CALLBACKS.set(0);
				WeightedTableResult table = evaluateWeightedPhysicalTable(dataset, compiled, group, weightedInput);
				int tableCallbacks = AGGREGATE_CALLBACKS.get();
				writeEvidence("weighted-custom-table-direct-adjacency-" + adjacency,
						"query:\n" + query + "\nadjacency=" + adjacency + "\nroute=NativeGroupResultCursor.tablePlan"
								+ "\nstreaming=false\nexpected=" + List.of(expectedSequence + "|2") + "\nactual="
								+ table.rows() + "\nfailure=" + table.failure() + "\ncustomCallbacks=" + tableCallbacks
								+ "\n");
				softly.assertThat(table.failure())
						.as("the non-streaming table consumes weighted custom rows exactly once, adjacency=%s",
								adjacency)
						.isNull();
				softly.assertThat(table.rows())
						.as("the physical table returns the exact independent custom and DISTINCT results")
						.containsExactly(expectedSequence + "|2");
				softly.assertThat(tableCallbacks)
						.as("one observable reducer callback occurs per logical solution, adjacency=%s", adjacency)
						.isEqualTo(16);
			}

			AGGREGATE_CALLBACKS.set(0);
			Observed automatic = evaluateWithStrategyEvents(repository, query,
					"weighted-custom-automatic-adjacency-" + adjacency, true, null);
			writeEvidence("weighted-custom-automatic-adjacency-" + adjacency,
					"query:\n" + query + "\nadjacency=" + adjacency + "\nexpected="
							+ List.of(expectedSequence + "|2") + "\nactual=" + aggregateResultRows(automatic.rows())
							+ "\ncustomCallbacks=" + automatic.aggregateCallbacks() + "\ntelemetry:\n"
							+ automatic.telemetry() + "\nstrategyEvents:\n"
							+ readStrategyEvents("weighted-custom-automatic-adjacency-" + adjacency));
			softly.assertThat(automatic.rows())
					.as("automatic weighted custom aggregate returns one exact row, adjacency=%s", adjacency)
					.hasSize(1);
			if (!automatic.rows().isEmpty()) {
				softly.assertThat(aggregateResultRows(automatic.rows()))
						.as("automatic adaptation preserves the exact custom and DISTINCT output")
						.containsExactly(expectedSequence + "|2");
			}
			softly.assertThat(automatic.aggregateCallbacks())
					.as("speculation and fallback cannot duplicate third-party custom callbacks, adjacency=%s",
							adjacency)
					.isEqualTo(16);
			softly.assertThat(automatic.telemetry())
					.as("the automatic control proves one actual native aggregate route")
					.contains("nativeInvocationsActual=1", "nativeExecutionPath=");

			String singlePatternQuery = PREFIX + "SELECT ?source (<" + ORDERED_AGGREGATE_IRI
					+ ">( ?value ) AS ?sequence) WHERE { ?source ex:input ?value } GROUP BY ?source";
			AGGREGATE_CALLBACKS.set(0);
			Observed singlePatternGeneric = evaluate(repository, singlePatternQuery, false, null);
			AGGREGATE_CALLBACKS.set(0);
			Observed singlePatternNative = evaluateWithStrategyEvents(repository, singlePatternQuery,
					"single-pattern-custom-adjacency-" + adjacency, true, null);
			Map<String, String> actualGroups = new HashMap<>();
			for (BindingSet row : singlePatternNative.rows()) {
				actualGroups.put(row.getValue("source").stringValue(), row.getValue("sequence").stringValue());
			}
			Map<String, String> expectedGroups = Map.of(EX + "source-A", "A1,A2", EX + "source-B", "B1,B2");
			writeEvidence("single-pattern-custom-adjacency-" + adjacency,
					"query:\n" + singlePatternQuery + "\nexpected=" + expectedGroups + "\ngeneric="
							+ aggregateGroups(singlePatternGeneric.rows()) + "\nactual=" + actualGroups
							+ "\ncustomCallbacks=" + singlePatternNative.aggregateCallbacks() + "\ntelemetry:\n"
							+ singlePatternNative.telemetry() + "\nstrategyEvents:\n"
							+ readStrategyEvents("single-pattern-custom-adjacency-" + adjacency));
			softly.assertThat(aggregateGroups(singlePatternGeneric.rows()))
					.as("the generic single-pattern aggregate has independent exact group values")
					.isEqualTo(expectedGroups);
			softly.assertThat(actualGroups)
					.as("native single-pattern admission retains each group's exact reducer sequence")
					.isEqualTo(expectedGroups);
			softly.assertThat(singlePatternNative.aggregateCallbacks())
					.as("the single-pattern custom reducer sees each input solution once")
					.isEqualTo(4);
			softly.assertThat(singlePatternNative.telemetry())
					.as("the single-pattern result was produced by a native aggregate execution")
					.contains("nativeInvocationsActual=1", "nativeExecutionPath=");
		}
		softly.assertAll();
	}

